const std = @import("std");

const Result = union(enum) { count: u32, name: []const u8 };

pub fn main() void {
    var values = [_]u32{2, 4, 8};
    for (&values, 0..) |*value, index| {
        value.* += @intCast(index);
    }

    const maybe: ?u32 = values[0];
    if (maybe) |value| std.debug.print("First: {d}\n", .{value});

    const result: Result = .{.name = "Aurora"};
    switch (result) {
        .count => |count| std.debug.print("{d}\n", .{count}),
        .name => |name| std.debug.print("{s}\n", .{name}),
    }
}

const std = @import("std");

fn Vector(comptime T: type, comptime size: usize) type {
    return struct {
        values: [size]T,

        fn sum(self: @This()) T {
            var total: T = 0;
            inline for (self.values) |value| total += value;
            return total;
        }
    };
}

pub fn main() void {
    const Vec = Vector(u32, 3);
    const vector: Vec = .{.values = .{1, 2, 3}};
    std.debug.print("Sum: {d}\n", .{vector.sum()});
}

const std = @import("std");

const Counter = struct {
    value: u32 = 0,

    fn increment(self: *Counter) void {
        self.value += 1;
    }
};

const State = enum { idle, ready };

pub fn main() void {
    var counter: Counter = .{};
    counter.increment();
    const state: State = .ready;
    std.debug.print("Count: {d}, state: {s}\n", .{counter.value, @tagName(state)});
}

const std = @import("std");

fn parse(text: []const u8) !u32 {
    if (text.len == 0) return error.Empty;
    return try std.fmt.parseInt(u32, text, 10);
}

fn defaultValue(value: ?u32) u32 {
    return value orelse 42;
}

pub fn main() void {
    const number = parse("17") catch |err| {
        std.debug.print("Could not parse: {s}\n", .{@errorName(err)});
        return;
    };
    std.debug.print("{d} / {d}\n", .{number, defaultValue(null)});
}

const std = @import("std");

pub fn main(init: std.process.Init) !void {
    var buffer: [1024]u8 = undefined;
    var output: std.Io.File.Writer = .init(.stdout(), init.io, &buffer);
    const writer = &output.interface;

    try greet(writer, "Zig 0.17.1");
    try writer.flush();
}

fn greet(writer: *std.Io.Writer, name: []const u8) !void {
    try writer.print("Hello, {s}!\n", .{name});
}

const std = @import("std");

pub fn main() !void {
    const gpa = std.heap.page_allocator;
    var values: std.ArrayList(u32) = .empty;
    defer values.deinit(gpa);

    try values.append(gpa, 17);
    try values.appendSlice(gpa, &.{21, 42});

    const text = try gpa.dupeSentinel(u8, "Current Zig", 0);
    defer gpa.free(text);

    std.debug.print("{s}: {any}\n", .{text, values.items});
}

const std = @import("std");

const User = struct {
    name: []const u8,
    active: bool = true,
};

pub fn main() void {
    const info = @typeInfo(User).@"struct";
    inline for (info.field_names, info.field_types) |name, T| {
        std.debug.print("{s}: {s}\n", .{name, @typeName(T)});
    }
    std.debug.print("Has name: {}\n", .{@hasField(User, "name")});
}

const std = @import("std");

const document =
    \\{
    \\  "title": "星空 🌌",
    \\  "version": "0.17.1"
    \\}
;

fn @"print document"(text: []const u8) void {
    // Quoted identifiers and multiline strings retain their original bytes.
    std.debug.print("{s}\n", .{text});
}

pub fn main() void {
    @"print document"(document);
}
